{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table MAPLEMONK.Bananaclub_Data_Scrapping_Fact_Items as WITH Myntra_Final AS ( SELECT CAST(DATE(TIMESTAMP(scraped_at)) AS DATE) AS scraped_date, mrp AS Myntra_MRP, brand, CAST(price AS FLOAT64) AS Myntra_price, stock, title Myntra_Product_name, gender, ROUND(CAST(rating AS FLOAT64), 1) rating, sku_id, page_no, COALESCE(mp.category, sm.Category) AS category, discount, COALESCE(mp.grammage, sm.SIZE) AS grammage, position, image_url, product_url, article_type, is_sponsored, listing_type, rating_count, COALESCE(mp.sub_category, sm.Sub_Category) AS sub_category, primary_color, is_best_seller, inventory_count, discount_display_label, sm.sku AS Summary_SKU, sm.Inventory Inventory, COALESCE(product_id, sm.Myntra_Style_ID) AS Myntra_Product_Id FROM `MAPLEMONK.Bananaclub_myntra_products` mp LEFT JOIN `MAPLEMONK.Google_sheet_bc_Summary` sm ON mp.product_id = sm.Myntra_Style_ID AND mp.grammage = sm.SIZE qualify row_number() over (partition by sku_id,product_id,scraped_date order by myntra_mrp desc)=1 ), Shopify_Data AS ( SELECT distinct JSON_EXTRACT_SCALAR(v, \'$.sku\') AS Shopify_sku, title AS shopify_product_name, JSON_EXTRACT_SCALAR(v, \'$.product_id\') AS Shopify_product_id, JSON_EXTRACT_SCALAR(v, \'$.title\') AS Shopify_size, JSON_EXTRACT_SCALAR(v, \'$.price\') AS Shopify_price, JSON_EXTRACT_SCALAR(v, \'$.compare_at_price\') AS Shopify_compare_at_price, JSON_EXTRACT_SCALAR(v, \'$.inventory_quantity\') AS Shopify_inventory, JSON_EXTRACT_SCALAR(i, \'$.src\') AS image_link FROM `MAPLEMONK.Shopify_BC_products` q LEFT JOIN UNNEST(q.variants) v LEFT JOIN UNNEST(q.images) i ) SELECT mf.*, sd.shopify_product_name, sd.Shopify_inventory, COALESCE(sd.Shopify_sku, mf.Summary_SKU) AS Shopify_sku, sd.Shopify_product_id, COALESCE(sd.Shopify_size,mf.grammage) AS Size, CAST(sd.Shopify_price AS FLOAT64) Shopify_price, COALESCE(sd.Shopify_compare_at_price,mf.Myntra_MRP) AS MRP, sd.image_link FROM Myntra_Final mf LEFT JOIN Shopify_Data sd ON mf.Summary_SKU = sd.Shopify_sku AND mf.grammage = sd.Shopify_size qualify row_number() over(partition by Shopify_sku,scraped_date order by MRP desc)=1; create or replace table MAPLEMONK.Bananaclub_Ajio_Data_Scrapping_Fact_Items as SELECT CAST(DATE(TIMESTAMP(scraped_at)) AS DATE) AS scraped_date ,coalesce(a.mrp, b.mrp) Ajio_mrp ,price Ajio_price ,sku ,b.Seller_SKU Ajio_sku ,rank ,tags ,brand ,coalesce(a.title,b.name) Product_name ,b.size ,b.Trade_discount ,rating ,keyword ,page_no ,discount ,position ,image_url ,product_url ,is_sponsored ,listing_type ,rating_count ,coupon_status from `MAPLEMONK.banana_club_scrapping_ajio_search` a LEFT JOIN( select MRP ,name ,size ,AjioCode ,Seller_SKU ,Trade_discount from `MAPLEMONK.Banana_club_Ajio_Mapping` qualify row_number() over (partition by AjioCode,Seller_SKU order by MRP desc) = 1) b ON LOWER(TRIM(a.sku)) = LOWER(TRIM(b.AjioCode)); create or replace table MAPLEMONK.Bananaclub_Flipkart_Data_Scrapping_Fact_Items as select CAST(DATE(TIMESTAMP(scraped_at)) AS DATE) AS scraped_date ,Size ,coalesce(a.mrp,b.Flipkart_MRP) FK_MRP ,coalesce(a.price,b.Flipkart_SP) FK_Price ,Seller_SKU_Id FK_sku ,coalesce(b.Flipkart_Serial_Number,a.product_id) sku ,discount ,coalesce(a.title,b.name) Product_Name ,category ,sub_category ,vertical ,brand ,keyword ,super_title ,item_id ,rating ,image_url ,rank ,in_stock ,listing_id ,page_string ,product_url ,is_sponsored ,rating_count ,review_count ,is_best_seller from `MAPLEMONK.banana_club_scrapping_flipkart_search` a left join( select Name ,Size ,Website_MRP ,Website_SP ,Flipkart_MRP ,Flipkart_SP ,Seller_SKU_Id ,Flipkart_Serial_Number from `MAPLEMONK.Banana_club_Flipkart_Mapping` qualify row_number() Over (partition by Seller_SKU_Id,Flipkart_Serial_Number order by Website_MRP desc)=1) b on lower(trim(a.product_id)) = lower(trim(b.Flipkart_Serial_Number)); create or replace table MAPLEMONK.Bananaclub_price_difference_Fact_Items as with myntra_shopify as( select scraped_date ,CAST(Myntra_MRP AS FLOAT64) Myntra_MRP ,CAST(MRP AS FLOAT64) MRP ,Myntra_price ,Shopify_price ,Summary_SKU Myntra_sku ,Shopify_sku ,image_link ,shopify_product_name ,Myntra_Product_name ,gender ,category ,sub_category ,Size from MAPLEMONK.Bananaclub_Data_Scrapping_Fact_Items qualify row_number() over(partition by Myntra_sku,Shopify_sku,scraped_date order by MRP desc)=1), Ajio_data as (select scraped_date ,Ajio_sku ,CAST(Ajio_mrp AS FLOAT64) Ajio_mrp ,CAST(Ajio_price AS FLOAT64) Ajio_price ,Product_name ,size ,image_url from MAPLEMONK.Bananaclub_Ajio_Data_Scrapping_Fact_Items qualify row_number() over(partition by Ajio_sku,scraped_date order by Ajio_mrp desc)=1), flipkart_data as ( select scraped_date ,FK_sku ,CAST(FK_MRP AS FLOAT64) FK_MRP ,CAST(FK_Price AS FLOAT64) FK_Price ,Product_Name ,Size ,category ,sub_category ,image_url from MAPLEMONK.Bananaclub_Flipkart_Data_Scrapping_Fact_Items qualify row_number() over(partition by FK_sku,scraped_date order by FK_MRP desc)=1) select ms.* ,Ajio_sku ,Ajio_mrp ,Ajio_price ,FK_sku ,FK_MRP ,FK_Price from myntra_shopify ms left join ajio_data aj on lower(ms.Myntra_sku)=lower(aj.Ajio_sku) and ms.scraped_date = aj.scraped_date left join flipkart_data fk on lower(ms.Myntra_sku)=lower(fk.FK_sku) and ms.scraped_date = fk.scraped_date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            